function [n] = survey_samples(t_orb, dt)
%SURVEY_SAMPLES  How many samples one orbit of t_orb [s] takes at dt [s]: every dt from the start to the orbit's end, both counted.
%   t_orb: real[1] (passed a plain number)
%   dt: real[1] (passed a plain number)
%   returns n: int (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    n = 0;
    n = (fix(floor((t_orb / dt))) + 1);
end
